/**
 * ai-overview.js — shared "Overview by AI" (#196) engine.
 *
 * A prose 1–2 page orientation, generated by running Claude AGENTICALLY over
 * CodeExam's own MCP tools: the model follows the orientation path in
 * AI_OVERVIEW_PROMPT, calling mcp__code-exam__* against the target index.
 * Non-air-gapped — shells out to the `claude` CLI with CE's own mcp-server
 * (src/mcp-server.js) pointed at an index directory.
 *
 * Shared by the GUI route (src/server.js `/api/ai-overview`) and the CLI
 * command (src/index.js `--overview-by-ai`) so the prompt + tool allow-list +
 * spawn plumbing can't drift between the two surfaces. The flow/prompt were
 * validated across six diverse indexes before this was wired.
 *
 * Deferred (#196 roadmap): small-codebase direct read, multi-provider/ensemble,
 * local-LLM (Qwen3) engine, AI↔non-AI merge.
 */

import { spawn } from 'child_process';
import fs from 'fs';
import os from 'os';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url)); // src/core
const MCP_SERVER = path.join(__dirname, '..', 'mcp-server.js');  // src/mcp-server.js

// The MCP tools the model is allowed to call. Comma-joined (no spaces) so the
// value rides the shell:true command line safely. Kept deliberately tight to
// the orientation path; digest/vocabulary/models_used are skipped by the model
// itself on minified targets (see prompt step 1).
export const AI_OVERVIEW_TOOLS = [
  'overview', 'vocabulary', 'digest', 'stats', 'list_files', 'list_classes',
  'entry_points', 'hotspots', 'models_used', 'command_catalog', 'regex_search',
  'search', 'call_tree', 'struct_dupes', 'show_file', 'referenced_resources',
].map(t => `mcp__code-exam__${t}`).join(',');

export const AI_OVERVIEW_PROMPT = `You are orienting a code examiner to an unfamiliar codebase using the CodeExam MCP tools (mcp__code-exam__*) over the currently-loaded index. Produce a 1-2 page PROSE summary (not bullet lists). Budget: ~5-8 tool calls; do not exceed ~5 digests.

1. DETECT THE TARGET'S SHAPE FIRST — call overview, then stats. Then choose a path:
   - Minified/bundled or binary-dominated (minified module names, .node/binary symbols like napi_*, huge per-file function counts): lead with command_catalog and regex_search on distinctive strings; do NOT call digest/vocabulary/models_used (they fail on minified code).
   - A collection (CE flags >=2 substantial top-level folders): orient PER-REPO with list_files <repo>/; do not summarize whole-tree.
   - Readable single project: overview -> vocabulary -> digest the top 3-5 key files (stop at ~5) -> models_used. Use command_catalog if it's a CLI/route app; regex_search for internal protocols/routes (e.g. /api/ or other internal route prefixes you observe); call_tree from an entry point for control flow. Call referenced_resources to surface the EXTERNAL surface — env vars, hosts/URLs, embedded SQL, external commands, and the data/config files the code reads/writes; if one data/config file dominates the references, call it out (use the reference counts, don't assume).
   - Always read the README/conventions for product framing if present (show_file on README*, CLAUDE.md, AGENTS.md).

2. SEPARATE host app from vendored/bundled dependencies. Density-ranked signals point at the largest dependency (e.g. an AWS SDK, an editor widget, native binaries), not the host. Say which is which.

3. RECOGNIZE CodeExam's own artifacts: .op files are CE binary-string captures (not a mystery); zip!-prefixed paths are archive members; single-letter names are expected in minified bundles. Don't flag these as findings.

4. ALWAYS include one AI/ML sentence, in one of three modes from models_used: detected (list the models, api vs local), none detected, or inconclusive-minified (IDs are var-held).

5. TEXT IS INDICIA, NOT GROUND TRUTH. Naming/comments/docs drift, and docs are often stale on active code. Distinguish RELIED-UPON (confirmed in code) from CONSIDERED (doc/name/comment-derived). When a claim rests on text the code doesn't confirm, say so (e.g. "from the README; not confirmed in code").

6. LEAN ON SIGNALS A CODE-GROVEL CAN'T COMPUTE: clones (struct_dupes), structural centrality (hotspots), IDF-ranked vocabulary, the external surface (referenced_resources: env vars / hosts / embedded SQL / referenced data files / commands aggregated across all call sites), host-vs-vendored split, what-was-skipped. This is CE's voice — don't write a generic summary a plain file read could produce.

OUTPUT (plain prose + two short labeled lists at the end):
- The 1-2 page prose summary (what it is, architecture, what it does, the AI/ML sentence). When the codebase is itself a layer over another system (e.g. as much a layer on git/GitHub as on an agent), name BOTH layers.
- "Where to look first / highest-payback CE commands" — each with one-line reasoning, including "skip these here" when a tool is defeated by the target.
- "Questions to start with" — each paired with the FIRST CE command to chase it (directed exploration, not noodling).
Emit file/function references as backticked paths (\`path\` or \`path@func\`) so they can be made clickable. Output ONLY the overview text; no preamble.`;

/**
 * Run "Overview by AI" against an index directory. Resolves with the prose
 * string (claude exit 0 + non-empty stdout) or rejects with an Error whose
 * message is safe to surface to the user.
 *
 * @param {object} opts
 * @param {string} opts.indexPath   Index directory to point the MCP server at (required).
 * @param {string} [opts.model]     Claude model id (e.g. claude-sonnet-4-6); omitted → CLI default.
 * @param {number} [opts.timeoutMs] Hard wall-clock limit (default 600000 = 10 min).
 * @param {(line:string)=>void} [opts.onStderr] Optional live stderr sink (CLI progress).
 * @returns {Promise<string>}
 */
export function runAiOverview({ indexPath, model, timeoutMs = 600000, onStderr } = {}) {
  return new Promise((resolve, reject) => {
    if (!indexPath) return reject(new Error('runAiOverview: indexPath is required.'));

    let tmpDir;
    try {
      // Neutral temp cwd → no CLAUDE.md autodiscovery for the spawned agent.
      tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'ce-ai-ov-'));
      const cfg = { mcpServers: { 'code-exam': { command: 'node', args: [MCP_SERVER, '--index-path', path.resolve(indexPath)] } } };
      fs.writeFileSync(path.join(tmpDir, 'mcp.json'), JSON.stringify(cfg));
    } catch (e) {
      return reject(new Error(`AI Overview setup failed: ${e.message}`));
    }

    let done = false;
    const cleanup = () => { try { fs.rmSync(tmpDir, { recursive: true, force: true }); } catch { /* ignore */ } };
    const finish = (fn, arg) => { if (done) return; done = true; cleanup(); fn(arg); };

    // Space-containing values stay off the (shell:true) command line: prompt via
    // stdin, mcp-config via a quoted file path, tools comma-separated.
    const args = ['-p', '--output-format', 'text',
      '--mcp-config', `"${path.join(tmpDir, 'mcp.json')}"`,
      '--allowedTools', AI_OVERVIEW_TOOLS,
      '--permission-mode', 'bypassPermissions'];
    if (model) args.push('--model', model);

    let child;
    try {
      child = spawn('claude', args, {
        cwd: tmpDir, shell: true, windowsHide: true,
        // Large indexes (e.g. .spinellis, ~6.8M lines) load synchronously in the
        // MCP server's startup (mcp-server.js main() loads the index before
        // server.connect()), so the default ~30s MCP startup timeout drops the
        // server before its tools register — Claude then reports "tools not
        // reachable". Raise MCP_TIMEOUT (ms) above this run's timeout so a slow
        // load still handshakes and any genuine failure surfaces as the clean
        // timeout below. (A handshake-first lazy-load in mcp-server.js is the
        // more robust follow-up.)
        env: { ...process.env, MCP_TIMEOUT: String(timeoutMs + 60000) },
      });
    } catch (e) {
      return finish(reject, new Error(`Could not launch the 'claude' CLI (AI Overview is non-air-gapped and needs it): ${e.message}`));
    }

    let out = '', err = '';
    child.stdout.on('data', (d) => { out += d; });
    child.stderr.on('data', (d) => { err += d; if (onStderr) onStderr(String(d)); });
    child.on('error', (e) => finish(reject, new Error(e.code === 'ENOENT'
      ? `The 'claude' CLI was not found on PATH. AI Overview is non-air-gapped and requires it.`
      : `AI Overview failed to launch: ${e.message}`)));
    const timer = setTimeout(() => {
      try { child.kill(); } catch { /* */ }
      finish(reject, new Error(`AI Overview timed out (${Math.round(timeoutMs / 60000)} min). Very large indexes (e.g. .spinellis) may need a longer --timeout.`));
    }, timeoutMs);
    child.on('close', (codeNum) => {
      clearTimeout(timer);
      if (codeNum === 0 && out.trim()) finish(resolve, out.trim());
      else finish(reject, new Error(`AI Overview failed (claude exit ${codeNum}). ${(err || '').slice(0, 400)}`.trim()));
    });
    child.stdin.write(AI_OVERVIEW_PROMPT);
    child.stdin.end();
  });
}
